/* Presentation layer; release scheduling and retained history stay in career-engine. */
header=function(title,desc,action=''){return `<div class="page-heading"><h1>${esc(names[current()]||title)}</h1>${action}</div>`};
const fullProfile=profile;
profile=function(){const template=document.createElement('template');template.innerHTML=fullProfile();const f=template.content.querySelector('#profile-form');f.querySelector('.panel-head').remove();f.querySelector('button[type="submit"]').textContent='Save profile';return header('Artist profile')+`<div class="profile-photo"><div class="profile-avatar">${state.profile.photo?`<img src="${esc(state.profile.photo)}" alt="Artist profile photo">`:esc((state.profile.artist||'U')[0])}</div><label class="text-link">Change photo<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${state.profile.photo?'<button class="text-link" id="remove-photo">Remove photo</button>':''}</div>`+f.outerHTML;};
overview=function(){const p=progress(),tasks=activeTasks().filter(t=>!['Done','Deferred'].includes(t.status)).slice(0,5),releases=state.releases.filter(r=>r.status!=='Archived');return header('Overview')+`<section class="workspace-banner"><div><h2>${state.profile.artist?esc(state.profile.artist):'Your workspace'}</h2><p>${esc(state.profile.goal||'Plan your next release.')}</p><a class="theme-btn-two" href="#releases">${releases.length?'View releases':'Create a release'}</a></div><img src="images/artists/dj.jpg" alt="DJ performing at the decks"></section><div class="stats-row">${[['Releases',releases.length],['Completed tasks',p.done],['Remaining tasks',p.total-p.done]].map(([label,value])=>`<div class="stat-box"><div class="stat-top">${label}</div><div class="stat-number">${value}</div></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Upcoming tasks</h2>${link('Roadmap','roadmap')}</div>${tasks.length?tasks.map(taskRow).join(''):empty('No upcoming tasks','Create a release or add a task.',btn('New task','add-task'))}</section><section class="panel"><div class="panel-head"><h2>Releases</h2>${link('View all','releases')}</div>${releases.length?releases.slice(0,4).map(r=>`<button class="release-summary" data-project="${r.id}"><img src="images/artists/speaker.jpg" alt=""><span><b>${esc(r.title)}</b><small>${esc(r.type)} · ${date(r.date)}</small></span><span class="tag">${esc(r.status)}</span></button>`).join(''):empty('Your first release','Choose a title, goal and date.',btn('Create release','add-release'))}</section></div>`;};
let taskLayout='list';const listResults=taskResults;taskResults=function(){if(taskLayout==='list')return listResults();const tasks=activeTasks().filter(t=>(releaseFilter==='all'||(releaseFilter==='general'?!t.releaseId:t.releaseId===releaseFilter))&&(taskFilter==='All'||t.status===taskFilter)&&t.title.toLowerCase().includes(query.toLowerCase()));return `<div class="task-board">${['To do','In progress','Done','Deferred'].map(status=>{const items=tasks.filter(t=>t.status===status);return `<section class="board-column"><h2>${status}<span>${items.length}</span></h2>${items.map(t=>`<article class="board-task"><button data-task="${t.id}">${esc(t.title)}</button><small>${esc(state.releases.find(r=>r.id===t.releaseId)?.title||'General career work')}</small>${E.blocked(state,t)?'<span class="tag">Waiting on prerequisite</span>':''}<small>${date(t.due)}</small><label><span class="visually-hidden">Status for ${esc(t.title)}</span><select data-board-status="${t.id}">${['To do','In progress','Done','Deferred'].map(v=>`<option ${v===t.status?'selected':''}>${v}</option>`).join('')}</select></label></article>`).join('')||'<p class="muted">No tasks</p>'}</section>`}).join('')}</div>`};
const listRoadmap=roadmap;roadmap=function(){return listRoadmap().replace('<div class="toolbar">',`<div class="view-switch" aria-label="Task layout"><button data-layout="list" aria-pressed="${taskLayout==='list'}" aria-label="List view" title="List view"><i class="fa-light fa-list" aria-hidden="true"></i></button><button data-layout="board" aria-pressed="${taskLayout==='board'}" aria-label="Board view" title="Board view"><i class="fa-light fa-columns-3" aria-hidden="true"></i></button></div><div class="toolbar">`)};
const baseRender=render;render=function(){baseRender();if(state.profile.photo)document.querySelector('.top-avatar').innerHTML=`<img src="${esc(state.profile.photo)}" alt="">`;const m=document.querySelector('#account-links');m.hidden=true;document.querySelector('#account-toggle').setAttribute('aria-expanded','false')};
const account=document.querySelector('.account-menu'),toggle=document.querySelector('#account-toggle'),links=document.querySelector('#account-links');function menu(open){links.hidden=!open;toggle.setAttribute('aria-expanded',String(open))}toggle.onclick=()=>menu(links.hidden);document.addEventListener('click',e=>{if(!account.contains(e.target))menu(false);const layout=e.target.closest('[data-layout]');if(layout){taskLayout=layout.dataset.layout;render()}if(e.target.closest('#remove-photo')){delete state.profile.photo;save('Photo removed.');render()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!links.hidden){menu(false);toggle.focus()}});
try{document.body.classList.toggle('sidebar-collapsed',localStorage.getItem('uniify-sidebar')==='collapsed')}catch{}
document.querySelector('#menu-toggle').onclick=()=>{if(innerWidth<900){const open=document.body.classList.toggle('nav-open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open))}else{const collapsed=document.body.classList.toggle('sidebar-collapsed');try{localStorage.setItem('uniify-sidebar',collapsed?'collapsed':'expanded')}catch{}document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(!collapsed))}};
document.querySelectorAll('.app-sidebar nav a').forEach(a=>{a.title=a.textContent;const text=document.createElement('span');text.textContent=a.textContent;a.childNodes.forEach(n=>{if(n.nodeType===3)n.remove()});a.append(text)});
document.addEventListener('change',async e=>{if(e.target.matches('[data-board-status]')){const t=state.tasks.find(t=>t.id===e.target.dataset.boardStatus);transition(t,e.target.value);adapt('Task status changed; prerequisites and suggested dates reviewed');save('Task updated.');render()}if(e.target.id==='profile-photo'){const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose a JPG, PNG or WebP under 10 MB.');return}try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const side=Math.min(bitmap.width,bitmap.height);canvas.getContext('2d').drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,256,256);state.profile.photo=canvas.toDataURL('image/jpeg',.85);bitmap.close();save('Photo saved.');render()}catch{toast('This image could not be opened.')}}});
if (!window.uniifyWorkspaceBooting) render();
account.addEventListener('focusout',()=>setTimeout(()=>{if(!account.contains(document.activeElement))menu(false)},0));
